<?php $current_level="current_level";$st_currentlevel="st_currentlevel";$level_aktif="level_aktif";$dbi="dbi";$namalengkap="namalengkap";$current_level="current_level";$btjugldt="tanggal";$namauser="namauser";require_once("clogin.php");require_once("config/dbi_connect.php");$namauser=$_SESSION["namauser"];$namalengkap=$_SESSION["nama_lengkap"];${$btjugldt}=date("Y-m-d");$level_aktif=$_SESSION["leveluser"];$current_level=mysqli_fetch_assoc(mysqli_query($dbi,"SELECT `urutan`, `level`, `alias` FROM `level` WHERE `level`='$level_aktif';"));$st_currentlevel=$current_level["alias"];echo "<!DOCTYPE html>\n<html lang="en">\n    <head>\n        <meta charset="utf-8\">\n        <meta http-equiv="X-UA-Compatible\" content=\"IE=edge\">\n        <meta name=\"viewport" content="width=device-width, initial-scale=1\">\n        <link rel=\"stylesheet" href=\"bootsrap337/w3.css\">\n        <link rel=\"stylesheet\" href="penyimpanan/penyimpanan.css\">\n        <link rel=\"stylesheet" href="bootsrap337/css/bootstrap.min.css\">\n    </head>\n    <style>\n        .inputkantong{height: 40px !important;\n        }\n    </style>\n    <body>\n        <div class="container-fluid\" style="margin: 30px;\">\n            <div class=\"row\">\n                <div class="col-xs-12">\n                    <h4 class="w3-text-theme w3-\">Cek kantong/produk darah level <b>";echo$st_currentlevel;echo "</b></h4>\n                </div>\n            </div>\n            <div class="row">\n                <div class="col-xs-12">\n                    <form name="FrmKantong\" id=\"FrmKantong" action="\" method=\"POST">\n                        <div class=\"panel w3-border-theme">\n                            <div class="panel-heading w3-theme-d5 clearfix w3-card-4" style=\"height:60px;\">\n                                <div class=\"col-xs-12 col-sm-8 col-md-6 text-left" style=\"font-size: 120%;font-weight: bold;\">\n                                    <div class="form-group" style=\"max-width: 320px;">\n                                        <div class=\"input-group inputkantong">\n                                            <span class=\"input-group-addon w3-theme-l4 inputkantong\">Barcode</span>\n                                            <input id="InpBarcode" name="InpBarcode\" type="text\" class=\"form-control inputkantong" placeholder=\" Nomor kantong\" autofocus autocomplete=\"off" required>    \n                                            <span class="input-group-btn\">\n                                                <button type="submit" id="SubmitScanBarcode\" name=\"SubmitScanBarcode" class="btn w3-theme-l1 w3-hover-yellow inputkantong"><i class=\"glyphicon glyphicon-compressed"></i></button>\n                                            </span>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"pull-right">\n                                    <div id=\"tload" style=\"display: none;\"><img src="profile/simdondar_loading1.gif"></div>\n                                </div>\n                            </div>\n                        </div>\n                    </form>\n                </div>\n            </div>\n            <div class="infokantong"></div>\n            <div class=\"row">\n                <div class=\"col-sm-12 text-center">\n                    <div id=\"barcodetmp" style="display: none\"></div>\n                    <div id="tload1\" style="display: none;\"><img src=\"profile/simdondar_loading1.gif\"></div>\n                    <button type=\"button\" class=\"w3-btn w3-white w3-border w3-border-red w3-round-large w3-card w3-hover-theme\" id="btndetail" style=\"display: none;\"> Tampilkan lebih detail <span class="glyphicon glyphicon-list-alt"></button>\n                </div>\n            </div>\n            <div class="infokantongdetail\"></div>\n        </div>\n        <!-- Modal Info Kantong Terkait -->\n        <div class=\"modal fade" id="MInfoTerkait\" role=\"dialog\">\n            <div class=\"modal-dialog modal-lg" role="document">   \n                <div class="modal-content\">\n                    <div class="modal-header w3-theme-d5 w3-card-4\">\n                        <h4 class="modal-title\" style="color:white;\">Informasi kantong </h4>\n                    </div>\n                    <div class=\"modal-body\">\n                        <div id=\"mtload\" class="text-center"><img src=\"penyimpanan/images/rubix.gif\" style="height: 200px;\"></div>\n                        <div class="modal-data"></div>\n                    </div>\n                    <div class="modal-footer\">\n                        <button class=\"w3-btn w3-theme-d4 w3-hover-red w3-card" data-dismiss="modal">Tutup</button>\n                    </div>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </body>\n</html>\n<script src="bootsrap337/js/jquery.min.js"></script>\n<script src="bootsrap337/js/bootstrap.min.js\"></script>\n<script>\n    \$(document).ready(function () {\n        \$('#InpBarcode').focus();\n        \$("#FrmKantong\").submit(function (event) {\n            var jbarcode=\$('#InpBarcode').val();\n            \$('#barcodetmp').text(jbarcode);\n            \$('#btndetail').hide();\n            \$.ajax({\n                type    : 'POST',\n                url     : 'penyimpanan/cek_kantongajax.php?mode=1',\n                data:\$(\"#FrmKantong input\").serialize(),\n                beforeSend:function(){\n                    \$('.infokantong').html('');\n                    \$('.infokantongdetail').html('');\n                    \$("#tload\").show();\n                },\n                success: function (data) {\n                    ex_data=data.split('|');\n                    \$('.infokantong').html(ex_data[0]);\n                    if(ex_data[1]=="1"){\n                        \$('#btndetail').show();\n                    }\n                },\n                complete:function(){\n                    \$('#tload').hide();\n                    \$('#InpBarcode').val('');\n                    \$('#InpBarcode').focus();\n                }                   \n            });\n            event.preventDefault();\n            return false;\n        })\n        \$('#btndetail').on('click', function(event) {\n            var jbarcode = \$('#barcodetmp').text()\n            event.preventDefault();\n            \$('#btndetail').hide();\n            \$.ajax({\n                type    : 'POST',\n                url     : 'penyimpanan/cek_kantongajax.php?mode=2',\n                data    : 'InpBarcode='+jbarcode,\n                beforeSend:function(){\n                    \$('.infokantongdetail').html('');\n                    \$(\"#tload1").show();\n                },\n                success: function (data) {\n                    ex_data=data.split('|');\n                    \$('.infokantongdetail').html(ex_data[0]);\n                    \$('#tload1').hide();\n                    \$('#InpBarcode').val('');\n                    \$('#InpBarcode').focus();\n                }\n            })\n        });\n    })\n    \$("#MInfoTerkait").on(\"hidden.bs.modal\", function(){\n        \$("#MInfoTerkait .modal-data\").html("\");\n        \$('#mtload').show();\n        \n    });\n\n    \$('#MInfoTerkait').on('shown.bs.modal', function (e) {\n            let jnokantong = \$(e.relatedTarget).attr('data-id');\n            \$('#MInfoTerkait .modal-title').html('Informasi kantong: '+jnokantong);\n            \$(\"#MInfoTerkait .modal-data").html(\"");\n            \$('#mtload').show();\n            \$.ajax({\n                type    : 'POST',\n                url     : 'penyimpanan/cek_kantongajax.php?mode=3',\n                data    : 'InpBarcode='+jnokantong,\n                success : function(data){\n                    ex_data=data.split('|');\n                    \$('#mtload').hide();\n                    \$("#MInfoTerkait .modal-data\").html(ex_data[0]);\n                }\n            });\n        });\n</script>\n";
